// v16 runtime layer (compiled from src/v16.ts; project uses global script mode)
const V16_GRIFFON={'初級':{hp:980,atk:34,drop:.18,barrier:180,breakTurns:3},'上級':{hp:1500,atk:48,drop:.38,barrier:330,breakTurns:3},'超級':{hp:2200,atk:63,drop:.65,barrier:560,breakTurns:2},'極':{hp:3100,atk:82,drop:1,barrier:900,breakTurns:2}};
for(const diff of Object.keys(V16_GRIFFON)){const q=QUESTS.find(x=>x.id===`a1_${diff}`),d=V16_GRIFFON[diff];if(q){q.hp=d.hp;q.atk=d.atk;q.dropRate=d.drop;q.gimmickText=`翠嵐障壁：火属性・バリアブレイカー・幻獣キラーが有効${diff==='極'?'。極では障壁が非常に厚い':''}`;q.v16Barrier=d.barrier;q.v16BreakTurns=d.breakTurns;}}
const V16_START=startQuest;startQuest=function(id){V16_START(id);const q=QUESTS.find(x=>x.id===id);if(!S.battle||q?.v7aid!=='a1')return;S.battle.v16BarrierMax=q.v16Barrier||0;S.battle.v16Barrier=S.battle.v16BarrierMax;S.battle.v16BreakTurns=0;save();render();};
const V16_HIT=hit;hit=function(dmg,label){const b=S.battle,q=b&&QUESTS.find(x=>x.id===b.questId);if(!b||q?.v7aid!=='a1'||!b.v16Barrier){V16_HIT(dmg,label);return;}const f=active(),u=M(f.id);let bd=Math.max(1,Math.floor(dmg));if(v11Has(u,'barrier_breaker'))bd=Math.floor(bd*1.5);b.v16Barrier=Math.max(0,b.v16Barrier-bd);b.log.push(`🛡 翠嵐障壁に ${bd} ダメージ`);if(b.v16Barrier<=0){b.v16BreakTurns=q.v16BreakTurns||2;b.log.push('💥 BARRIER BREAK! 攻撃の好機！');}};
const V16_NEXT=nextTurn;nextTurn=function(){const b=S.battle,q=b&&QUESTS.find(x=>x.id===b.questId);if(b&&q?.v7aid==='a1'&&b.v16Barrier<=0&&b.v16BreakTurns>0){b.v16BreakTurns--;if(b.v16BreakTurns<=0&&b.enemyHp>0){b.v16Barrier=b.v16BarrierMax;b.log.push('🛡 翠嵐障壁が再展開された');}}V16_NEXT();};
const V16_BATTLE=battleView;battleView=function(m){V16_BATTLE(m);const b=S.battle,q=b&&QUESTS.find(x=>x.id===b.questId);if(!b||q?.v7aid!=='a1')return;const enemy=document.querySelector('.v10-enemy');if(enemy){const pct=Math.max(0,Math.min(100,Math.round((b.v16Barrier/(b.v16BarrierMax||1))*100)));enemy.insertAdjacentHTML('beforeend',`<div class="v16-barrier"><span>🛡 翠嵐障壁</span><b>${b.v16Barrier>0?`${b.v16Barrier}/${b.v16BarrierMax}`:'BREAK!'}</b><div><i style="width:${pct}%"></i></div></div>`);}};
const V16_ADVENT_CARD=v7QuestCard;v7QuestCard=function(q){const html=V16_ADVENT_CARD(q);if(q?.v7aid!=='a1')return html;return html.replace('</div>',`<div class="tiny v16-fit">適正：🔥 火属性　🛡 バリアブレイカー　◆ 幻獣キラー</div></div>`);};
const V16_HEADER=header;header=function(){return V16_HEADER().replace('TYPE SCRIPT v15','TYPE SCRIPT v16').replace('TYPE SCRIPT v14','TYPE SCRIPT v16')};S.version=16;save();render();
